import { Injectable } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { firstValueFrom } from 'rxjs';
import { HttpClient, HttpParams } from '@angular/common/http';
import { downloadList } from '../../interfaces/download.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Injectable({
  providedIn: 'root'
})
export class DownloadService {
  urlApi: string = `${environment.downloadapiservice}`;
  url: string = `${environment.downloadservice}`;
  constructor(private http: HttpClient, private tost: TostbarService) { }


  async getDownloadJobs(nCaseid: string, PageNumber: number, cSortBy: 'N' | 'O', nDPid?: string): Promise<downloadList[]> {
    let params = new HttpParams().set('nCaseid', nCaseid).set('PageNumber', PageNumber.toString()).set('cSortBy', cSortBy);
    try {
      if (nDPid) {
        params = params.set('nDPid', nDPid); // Reset PageNumber to 1 if nDPid is provided
      }
      return await firstValueFrom(
        this.http.get<downloadList[]>(
          `${this.urlApi}/getdownload`, { params: params }
        )
      );
    } catch (error) {
      console.error('Error fetching download information:', error);
      this.tost.error('Error fetching download information');
      return [];
    }
  }


  async getDonwloadURL(nDPid: string): Promise<string> {
    const params = new HttpParams().set('nDPid', nDPid);
    try {
      const { cUrl } = await firstValueFrom(
        this.http.get<{ cUrl: string }>(
          `${this.urlApi}/get/url`, { params: params }
        )
      );
      return cUrl;
    } catch (error) {
      console.error('Error fetching presigned URL:', error);
      this.tost.error('Error fetching presigned URL');
      return null;
    }
  }

  async downloadFiles(mdl: { nCaseid: string, nSectionid: string, jFolders: string, jFiles: string, isHyperlink: boolean }): Promise<{ nDPid: string, msg: number, value: string }> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<{ nDPid: string, msg: number, value: string }>(`${this.urlApi}/startdownload`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.error(err["error"]?.message || 'Error downloading files');
      return { nDPid: '', msg: 0, value: 'Error download file' };
    }
  }

  async retryJob(nDPid: string): Promise<{ msg: number, value: string, error?: any }> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<{ msg: number, value: string, error?: any }>(`${this.urlApi}/retryjob`, { nDPid })
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.error('Error retry');
      return { msg: 0, value: 'Error Retry' };
    }
  }



  async deleteJob(nDPid: string): Promise<{ msg: number, value: string, error?: any }> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<{ msg: number, value: string, error?: any }>(`${this.urlApi}/delete`, { nDPid })
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.error('Error retry');
      return { msg: 0, value: 'Error Delete' };
    }
  }



  // async getApproximateUrl(mdl: { nCaseid: string, nSectionid: string, jFolders: string, jFiles: string,nMasterid:string }): Promise<{ msg: 1 | -1, cFinalSize: number, isValidForStream: boolean }> {
  //   const params = new HttpParams().set('nCaseid', mdl.nCaseid).set('nSectionid', mdl.nSectionid).set('jFolders', mdl.jFolders).set('jFiles', mdl.jFiles).set('nMasterid',mdl.nMasterid);
  async getApproximateUrl(mdl: { nCaseid: string, nSectionid: string, jFolders: string, jFiles: string, nMasterid: string, isHyperlink: boolean }): Promise<{ msg: 1 | -1, cFinalSize: number, isValidForStream: boolean }> {
    const params = new HttpParams().set('nCaseid', mdl.nCaseid).set('nSectionid', mdl.nSectionid).set('jFolders', mdl.jFolders).set('jFiles', mdl.jFiles).set('nMasterid', mdl.nMasterid).set('bIshyperlink', mdl.isHyperlink);

    try {
      const res = await firstValueFrom(
        this.http.get<{ msg: 1 | -1, cFinalSize: number, isValidForStream: boolean }>(
          `${this.url}/download/approximate/size`, { params: params }
        )
      );
      return res;
    } catch (error) {
      console.error('Error fetching approximate size:', error);
      this.tost.error('Error fetching approximate size');
      return null;
    }
  }
}